// =====================================================================
// Normalize & Verify Event
// n8n-hubspot-voicemail-audio-drop-transcriber
// dhRobin Systems · MIT License · Provided as-is, see DISCLAIMER.md
// ---------------------------------------------------------------------
// Mode: Run Once for All Items
// 1. Detects the provider (Aircall JSON webhook or Twilio form-encoded callback)
// 2. Verifies authenticity (Aircall webhook token / Twilio X-Twilio-Signature)
// 3. Accepts only voicemail (and optionally call-recording) events with audio
// 4. Validates the audio URL against a host allow-list (SSRF guard)
// 5. Normalises the caller number, checks duration limits and idempotency
// Emits `action`: accepted | skip_* | rejected | error
// =====================================================================
// ---------- Shared helpers (inlined into each Code node at build time) ----------
const ENV = (() => { try { return $env || {}; } catch (e) { return {}; } })();
const env = (key, fallback) => {
  const v = ENV[key];
  return v === undefined || v === null || String(v).trim() === '' ? fallback : String(v).trim();
};
const isOn  = (key) => env(key, 'true').toLowerCase() !== 'false';   // fail-safe: ON unless exactly "false"
const optIn = (key) => env(key, 'false').toLowerCase() === 'true';   // opt-in: OFF unless exactly "true"
const csv   = (key, fallback) => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);
const int   = (key, fallback) => { const n = parseInt(env(key, String(fallback)), 10); return Number.isFinite(n) ? n : fallback; };
const looksPlaceholder = (v) => /YOUR_|PLACEHOLDER|CHANGE_ME|REPLACE_/i.test(String(v || ''));
const DRY_RUN = isOn('DRY_RUN');
const SANDBOX_MODE = isOn('SANDBOX_MODE');
const EFFECTIVE_DRY_RUN = DRY_RUN || SANDBOX_MODE; // live writes need BOTH flags off
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
function redactSecrets(t) {
  return String(t || '')
    .replace(/Bearer\s+[A-Za-z0-9\-_.=]+/gi, 'Bearer [REDACTED]')
    .replace(/Basic\s+[A-Za-z0-9+/=]{8,}/gi, 'Basic [REDACTED]')
    .replace(/pat-[a-z0-9]{2,}-[A-Za-z0-9-]+/gi, '[REDACTED_TOKEN]')
    .replace(/sk-[A-Za-z0-9_-]{10,}/g, '[REDACTED_KEY]')
    .replace(/\bAC[0-9a-fA-F]{32}\b/g, '[REDACTED_TWILIO_SID]')
    .replace(/https?:\/\/([^\s/"'?#]+)[^\s"']*/gi, 'https://$1/[REDACTED_PATH]')
    .slice(0, 200);
}
const sanitizeError = (err) => {
  const status = err?.httpCode || err?.statusCode || err?.response?.status || err?.cause?.status || null;
  return { status: status ? Number(status) : null, message: redactSecrets(err?.message || 'Unknown error') };
};
function safeEqual(a, b) {
  a = String(a || ''); b = String(b || '');
  let diff = a.length ^ b.length;
  const n = Math.max(a.length, b.length);
  for (let i = 0; i < n; i++) diff |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0);
  return diff === 0 && a.length > 0;
}
const maskCards = (s) => String(s || '').replace(/\b(?:\d[ -]?){13,19}\b/g, '[CARD_OR_ACCOUNT_NUMBER]');
const redactPII = (s) => maskCards(s)
  .replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, '[EMAIL]')
  .replace(/(?:\+?\d{1,3}[\s.-]?)?(?:\(\d{2,4}\)[\s.-]?|\d{3}[\s.-])?\d{3}[\s.-]\d{4}\b/g, '[PHONE]');
const staticData = (() => { try { return $getWorkflowStaticData('global'); } catch (e) { return {}; } })();
// ---------- end shared helpers ----------

const CONFIG = {
  PROVIDER:                     env('VOICE_PROVIDER', 'auto').toLowerCase(),          // auto | aircall | twilio
  AIRCALL_WEBHOOK_TOKEN:        env('AIRCALL_WEBHOOK_TOKEN', ''),
  TWILIO_AUTH_TOKEN:            env('TWILIO_AUTH_TOKEN', ''),
  PUBLIC_WEBHOOK_URL:           env('PUBLIC_WEBHOOK_URL', ''),
  ACCEPTED_AIRCALL_EVENTS:      csv('ACCEPTED_AIRCALL_EVENTS', 'call.voicemail_left'),
  TRANSCRIBE_CALL_RECORDINGS:   optIn('TRANSCRIBE_CALL_RECORDINGS'),
  MIN_AUDIO_SECONDS:            Math.max(0, int('MIN_AUDIO_SECONDS', 3)),
  MAX_AUDIO_SECONDS:            Math.max(10, int('MAX_AUDIO_SECONDS', 600)),
  AUDIO_HOST_ALLOWLIST:         csv('AUDIO_HOST_ALLOWLIST', 'api.twilio.com,.aircall.io,.amazonaws.com').map((h) => h.toLowerCase()),
  DEFAULT_COUNTRY_CALLING_CODE: env('DEFAULT_COUNTRY_CALLING_CODE', '1').replace(/\D/g, ''),
};

function detectProvider(body) {
  if (CONFIG.PROVIDER === 'aircall' || CONFIG.PROVIDER === 'twilio') return CONFIG.PROVIDER;
  if (body && typeof body === 'object' && body.event && body.data && (body.resource === 'call' || String(body.event).startsWith('call.'))) return 'aircall';
  if (body && typeof body === 'object' && (body.RecordingSid || body.CallSid || body.AccountSid)) return 'twilio';
  return null;
}

function verifyAircall(body) {
  const expected = CONFIG.AIRCALL_WEBHOOK_TOKEN;
  if (!expected || looksPlaceholder(expected)) return { ok: false, reason: 'aircall_webhook_token_not_configured' };
  return safeEqual(expected, body.token) ? { ok: true, reason: 'aircall_token_valid' } : { ok: false, reason: 'aircall_token_mismatch' };
}

// Twilio: base64(HMAC-SHA1(authToken, fullUrl + concat(sorted(key + value)))) == X-Twilio-Signature
function verifyTwilio(item, body) {
  const token = CONFIG.TWILIO_AUTH_TOKEN;
  if (!token || looksPlaceholder(token)) return { ok: false, reason: 'twilio_auth_token_not_configured' };
  let crypto;
  try { crypto = require('crypto'); } catch (e) { return { ok: false, reason: 'crypto_module_not_allowed_set_NODE_FUNCTION_ALLOW_BUILTIN' }; }
  const headers = Object.fromEntries(Object.entries(item.headers || {}).map(([k, v]) => [k.toLowerCase(), v]));
  const signature = headers['x-twilio-signature'];
  if (!signature) return { ok: false, reason: 'twilio_signature_header_missing' };
  const url = CONFIG.PUBLIC_WEBHOOK_URL || item.webhookUrl || '';
  const data = url + Object.keys(body).sort().map((k) => `${k}${body[k]}`).join('');
  const expected = crypto.createHmac('sha1', token).update(Buffer.from(data, 'utf-8')).digest('base64');
  return safeEqual(expected, signature) ? { ok: true, reason: 'twilio_signature_valid' } : { ok: false, reason: 'twilio_signature_mismatch' };
}

function allowedAudioUrl(raw) {
  let u;
  try { u = new URL(String(raw)); } catch (e) { return null; }
  if (u.protocol !== 'https:' || u.username || u.password) return null;
  const host = u.hostname.toLowerCase();
  const ok = CONFIG.AUDIO_HOST_ALLOWLIST.some((h) => (h.startsWith('.') ? host.endsWith(h) : host === h));
  return ok ? u.toString() : null;
}

function normalizeNumber(raw) {
  const s = String(raw || '').trim();
  if (!s || /anonymous|restricted|unknown|private/i.test(s)) return null;
  const digits = s.replace(/\D/g, '');
  if (digits.length < 7 || digits.length > 15) return null;
  const cc = CONFIG.DEFAULT_COUNTRY_CALLING_CODE;
  const e164 = s.startsWith('+') || s.startsWith('00') ? `+${digits.replace(/^00/, '')}` : (cc && digits.length <= 10 ? `+${cc}${digits}` : `+${digits}`);
  const full = e164.slice(1);
  const national = cc && full.startsWith(cc) ? full.slice(cc.length) : full;
  const masked = `${e164.slice(0, Math.min(3, e164.length - 4))}•••${e164.slice(-4)}`;
  return { e164, national, masked };
}

function toIso(v) {
  if (v === undefined || v === null || v === '') return null;
  const n = Number(v);
  const d = Number.isFinite(n) ? new Date(n < 1e12 ? n * 1000 : n) : new Date(String(v));
  return isNaN(d.getTime()) ? null : d.toISOString();
}

function extract(provider, body) {
  if (provider === 'aircall') {
    const d = body.data || {};
    const event = String(body.event || '');
    let audioUrl = null; let kind = null;
    if (event === 'call.voicemail_left' || (CONFIG.ACCEPTED_AIRCALL_EVENTS.includes(event) && d.voicemail)) { audioUrl = d.voicemail; kind = 'voicemail'; }
    else if (CONFIG.TRANSCRIBE_CALL_RECORDINGS && event === 'call.ended' && d.recording) { audioUrl = d.recording; kind = 'call_recording'; }
    return {
      event, kind, accepted: CONFIG.ACCEPTED_AIRCALL_EVENTS.includes(event) || (CONFIG.TRANSCRIBE_CALL_RECORDINGS && event === 'call.ended'),
      callId: d.id !== undefined ? String(d.id) : null,
      audioUrl,
      durationSec: Number(d.duration) || null,
      startedAt: toIso(d.started_at) || toIso(body.timestamp) || new Date().toISOString(),
      callerRaw: d.direction === 'outbound' ? null : (d.raw_digits || null),
      lineName: d.number && (d.number.name || d.number.digits) ? String(d.number.name || d.number.digits).slice(0, 80) : null,
      agentName: d.user && d.user.name ? String(d.user.name).slice(0, 80) : null,
      secureLink: d.asset || null, // Aircall secured asset link (requires an Aircall login), safe to store
      status: null,
    };
  }
  // Twilio <Record action> callback or recordingStatusCallback (form-encoded, parsed by the Webhook node)
  const status = body.RecordingStatus ? String(body.RecordingStatus).toLowerCase() : null;
  const url = body.RecordingUrl ? String(body.RecordingUrl) : null;
  return {
    event: status ? `recording.${status}` : 'record.action',
    kind: 'voicemail',
    accepted: true,
    callId: body.RecordingSid ? String(body.RecordingSid) : (body.CallSid ? String(body.CallSid) : null),
    audioUrl: url ? (/\.(mp3|wav)$/i.test(url) ? url : `${url}.mp3`) : null,
    durationSec: Number(body.RecordingDuration) || null,
    startedAt: toIso(body.RecordingStartTime) || new Date().toISOString(),
    callerRaw: body.From || body.Caller || null,
    lineName: body.To ? String(body.To).slice(0, 40) : null,
    agentName: null,
    secureLink: null, // Twilio recording URLs need account credentials; see AUDIO_LINK_MODE
    status,
  };
}

const inputs = $input.all();
const results = [];
const evaluatedAt = new Date().toISOString();
const mode = { dryRun: EFFECTIVE_DRY_RUN, sandbox: SANDBOX_MODE };
const processed = staticData.processed || {};
const seen = new Set();

for (let i = 0; i < inputs.length; i++) {
  const item = inputs[i].json || {};
  const body = item.body && typeof item.body === 'object' ? item.body : {};
  const emit = (action, extra = {}) => results.push({ json: { action, evaluatedAt, mode, ...extra }, pairedItem: { item: i } });

  const provider = detectProvider(body);
  if (!provider) { emit('skip_unknown_payload', { reason: 'not_an_aircall_or_twilio_event' }); continue; }

  const auth = provider === 'aircall' ? verifyAircall(body) : verifyTwilio(item, body);
  if (!auth.ok && !SANDBOX_MODE) { emit('rejected', { provider, reason: 'unauthenticated_request' }); continue; }

  const ev = extract(provider, body);
  const base = { provider, event: ev.event, callId: ev.callId, authCheck: auth.reason, correlationId: `${provider}-${ev.callId || 'unknown'}-${Date.now()}` };

  if (!ev.accepted) { emit('skip_event_type', { ...base, reason: `event_not_accepted:${ev.event}` }); continue; }
  if (!ev.callId || !/^[A-Za-z0-9_-]{1,64}$/.test(ev.callId)) { emit('error', { ...base, callId: null, reason: 'invalid_or_missing_call_id' }); continue; }
  const key = `${provider}:${ev.callId}`;
  if (seen.has(key)) { emit('skip_duplicate_event', { ...base, reason: 'already_in_this_batch' }); continue; }
  seen.add(key);
  if (processed[key]) { emit('skip_already_processed', { ...base, reason: 'note_already_created', processedAt: new Date(processed[key].at).toISOString() }); continue; }
  if (ev.status && ev.status !== 'completed') { emit('skip_recording_not_completed', { ...base, reason: `recording_status_${ev.status}` }); continue; }
  if (!ev.audioUrl) { emit('skip_no_audio', { ...base, reason: 'event_has_no_audio_url' }); continue; }
  const audioUrl = allowedAudioUrl(ev.audioUrl);
  if (!audioUrl) { emit('rejected', { ...base, reason: 'audio_url_not_in_AUDIO_HOST_ALLOWLIST' }); continue; }
  if (ev.durationSec !== null && ev.durationSec < CONFIG.MIN_AUDIO_SECONDS) { emit('skip_audio_too_short', { ...base, reason: `duration_${ev.durationSec}s_below_${CONFIG.MIN_AUDIO_SECONDS}s` }); continue; }
  if (ev.durationSec !== null && ev.durationSec > CONFIG.MAX_AUDIO_SECONDS) { emit('skip_audio_too_long', { ...base, reason: `duration_${ev.durationSec}s_above_${CONFIG.MAX_AUDIO_SECONDS}s` }); continue; }
  const caller = normalizeNumber(ev.callerRaw);
  if (!caller) { emit('skip_missing_caller_number', { ...base, reason: 'caller_number_missing_withheld_or_invalid' }); continue; }
  const secureLink = ev.secureLink ? allowedAudioUrl(ev.secureLink) : null;

  emit('accepted', {
    ...base,
    idempotencyKey: key,
    kind: ev.kind,
    audioUrl,
    secureLink,
    durationSec: ev.durationSec,
    startedAt: ev.startedAt,
    caller,
    lineName: ev.lineName,
    agentName: ev.agentName,
    isTwilio: provider === 'twilio',
    reason: 'voicemail_ready',
  });
}

return results;

// =====================================================================
// Resolve HubSpot Records
// n8n-hubspot-voicemail-audio-drop-transcriber
// dhRobin Systems · MIT License · Provided as-is, see DISCLAIMER.md
// ---------------------------------------------------------------------
// Mode: Run Once for All Items
// Finds the HubSpot contact for the caller number BEFORE any audio is
// downloaded or transcribed, so unknown callers cost nothing.
//   1. POST /crm/v3/objects/contacts/search   (phone / mobile / searchable number fields)
//   2. GET  /crm/v3/objects/contacts/{id}?associations=deals,companies
//   3. POST /crm/v3/objects/deals/batch/read  (primary open deal selection)
// Emits `action`: transcribe | skip_unknown_caller | skip_ambiguous_caller | error
// =====================================================================
// ---------- Shared helpers (inlined into each Code node at build time) ----------
const ENV = (() => { try { return $env || {}; } catch (e) { return {}; } })();
const env = (key, fallback) => {
  const v = ENV[key];
  return v === undefined || v === null || String(v).trim() === '' ? fallback : String(v).trim();
};
const isOn  = (key) => env(key, 'true').toLowerCase() !== 'false';   // fail-safe: ON unless exactly "false"
const optIn = (key) => env(key, 'false').toLowerCase() === 'true';   // opt-in: OFF unless exactly "true"
const csv   = (key, fallback) => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);
const int   = (key, fallback) => { const n = parseInt(env(key, String(fallback)), 10); return Number.isFinite(n) ? n : fallback; };
const looksPlaceholder = (v) => /YOUR_|PLACEHOLDER|CHANGE_ME|REPLACE_/i.test(String(v || ''));
const DRY_RUN = isOn('DRY_RUN');
const SANDBOX_MODE = isOn('SANDBOX_MODE');
const EFFECTIVE_DRY_RUN = DRY_RUN || SANDBOX_MODE; // live writes need BOTH flags off
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
function redactSecrets(t) {
  return String(t || '')
    .replace(/Bearer\s+[A-Za-z0-9\-_.=]+/gi, 'Bearer [REDACTED]')
    .replace(/Basic\s+[A-Za-z0-9+/=]{8,}/gi, 'Basic [REDACTED]')
    .replace(/pat-[a-z0-9]{2,}-[A-Za-z0-9-]+/gi, '[REDACTED_TOKEN]')
    .replace(/sk-[A-Za-z0-9_-]{10,}/g, '[REDACTED_KEY]')
    .replace(/\bAC[0-9a-fA-F]{32}\b/g, '[REDACTED_TWILIO_SID]')
    .replace(/https?:\/\/([^\s/"'?#]+)[^\s"']*/gi, 'https://$1/[REDACTED_PATH]')
    .slice(0, 200);
}
const sanitizeError = (err) => {
  const status = err?.httpCode || err?.statusCode || err?.response?.status || err?.cause?.status || null;
  return { status: status ? Number(status) : null, message: redactSecrets(err?.message || 'Unknown error') };
};
function safeEqual(a, b) {
  a = String(a || ''); b = String(b || '');
  let diff = a.length ^ b.length;
  const n = Math.max(a.length, b.length);
  for (let i = 0; i < n; i++) diff |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0);
  return diff === 0 && a.length > 0;
}
const maskCards = (s) => String(s || '').replace(/\b(?:\d[ -]?){13,19}\b/g, '[CARD_OR_ACCOUNT_NUMBER]');
const redactPII = (s) => maskCards(s)
  .replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, '[EMAIL]')
  .replace(/(?:\+?\d{1,3}[\s.-]?)?(?:\(\d{2,4}\)[\s.-]?|\d{3}[\s.-])?\d{3}[\s.-]\d{4}\b/g, '[PHONE]');
const staticData = (() => { try { return $getWorkflowStaticData('global'); } catch (e) { return {}; } })();
// ---------- end shared helpers ----------

const HUBSPOT_API_BASE = 'https://api.hubapi.com'; // fixed: the token is never sent anywhere else
const CONFIG = {
  HUBSPOT_ACCESS_TOKEN:   env('HUBSPOT_ACCESS_TOKEN', ''),
  UNKNOWN_CALLER_POLICY:  env('UNKNOWN_CALLER_POLICY', 'skip').toLowerCase(),        // skip | fallback_contact
  FALLBACK_CONTACT_ID:    /^\d{1,20}$/.test(env('FALLBACK_CONTACT_ID', '')) ? env('FALLBACK_CONTACT_ID', '') : '',
  MULTIPLE_MATCH_POLICY:  env('MULTIPLE_MATCH_POLICY', 'most_recent').toLowerCase(), // most_recent | skip
  NOTE_DEAL_LINK_MODE:    env('NOTE_DEAL_LINK_MODE', 'primary_open').toLowerCase(),  // primary_open | all | none
  MAX_ASSOCIATIONS:       Math.min(25, Math.max(1, int('MAX_ASSOCIATIONS_PER_TYPE', 5))),
};
if (!SANDBOX_MODE && (!CONFIG.HUBSPOT_ACCESS_TOKEN || looksPlaceholder(CONFIG.HUBSPOT_ACCESS_TOKEN))) {
  throw new Error('SANDBOX_MODE=false requires a real HUBSPOT_ACCESS_TOKEN environment variable.');
}

// Fictional directory used only in sandbox mode.
const SANDBOX_DIRECTORY = {
  '+12025550142': {
    contactId: '9601', contactName: 'Taylor Brooks (fictional)', contactOwnerId: 'OWNER_ID_AE_1',
    deals: [{ id: '9701', isClosed: false, lastModified: '2026-11-12T16:00:00Z' }, { id: '9702', isClosed: true, lastModified: '2026-06-01T09:00:00Z' }],
    companies: ['9801'],
  },
};

const helpers = this.helpers;
async function hubspot(method, path, body) {
  if (!helpers || typeof helpers.httpRequest !== 'function') throw new Error('this.helpers.httpRequest is not available in this n8n version.');
  const options = { method, url: `${HUBSPOT_API_BASE}${path}`, json: true, timeout: 15000,
    headers: { Authorization: `Bearer ${CONFIG.HUBSPOT_ACCESS_TOKEN}`, 'Content-Type': 'application/json' } };
  if (body) options.body = body;
  for (let attempt = 1; attempt <= 3; attempt++) {
    try { return await helpers.httpRequest(options); }
    catch (err) {
      const safe = sanitizeError(err);
      if ((safe.status === 429 || (safe.status && safe.status >= 500)) && attempt < 3) { await sleep(1000 * attempt); continue; }
      const e = new Error(`HubSpot ${method} ${path.split('?')[0]} failed`); e.safe = safe; throw e;
    }
  }
}

function primaryDeal(details) {
  if (!details.length) return null;
  const byRecent = [...details].sort((a, b) => String(b.lastModified || '').localeCompare(String(a.lastModified || '')));
  return (byRecent.find((d) => !d.isClosed) || byRecent[0]).id;
}
const pickDeals = (details, allIds) => (CONFIG.NOTE_DEAL_LINK_MODE === 'none' ? []
  : CONFIG.NOTE_DEAL_LINK_MODE === 'all' ? allIds.slice(0, CONFIG.MAX_ASSOCIATIONS)
  : [primaryDeal(details) || allIds[0]].filter(Boolean));

async function findContacts(caller) {
  const groups = [
    { filters: [{ propertyName: 'phone', operator: 'EQ', value: caller.e164 }] },
    { filters: [{ propertyName: 'mobilephone', operator: 'EQ', value: caller.e164 }] },
    { filters: [{ propertyName: 'hs_searchable_calculated_phone_number', operator: 'EQ', value: caller.national }] },
    { filters: [{ propertyName: 'hs_searchable_calculated_mobile_number', operator: 'EQ', value: caller.national }] },
  ];
  const res = await hubspot('POST', '/crm/v3/objects/contacts/search', {
    filterGroups: groups, properties: ['firstname', 'lastname', 'hubspot_owner_id', 'lastmodifieddate'],
    sorts: [{ propertyName: 'lastmodifieddate', direction: 'DESCENDING' }], limit: 10,
  });
  return (res && res.results) || [];
}

async function loadContact(contactId) {
  const c = await hubspot('GET', `/crm/v3/objects/contacts/${encodeURIComponent(contactId)}?properties=firstname,lastname,hubspot_owner_id&associations=deals,companies`);
  const p = (c && c.properties) || {};
  const ids = (k) => [...new Set(((c && c.associations && c.associations[k] && c.associations[k].results) || []).map((r) => String(r.id)))];
  const dealIds = ids('deals');
  let details = [];
  if (dealIds.length > 1 && CONFIG.NOTE_DEAL_LINK_MODE === 'primary_open') {
    try {
      const res = await hubspot('POST', '/crm/v3/objects/deals/batch/read', { inputs: dealIds.slice(0, 100).map((id) => ({ id })), properties: ['hs_is_closed', 'hs_lastmodifieddate'] });
      details = ((res && res.results) || []).map((d) => ({ id: String(d.id), isClosed: String((d.properties || {}).hs_is_closed) === 'true', lastModified: (d.properties || {}).hs_lastmodifieddate || null }));
    } catch (e) { details = []; }
  }
  return {
    contactId: String(contactId),
    contactName: [p.firstname, p.lastname].filter(Boolean).join(' ').slice(0, 80) || `Contact ${contactId}`,
    contactOwnerId: p.hubspot_owner_id ? String(p.hubspot_owner_id) : null,
    dealIds: pickDeals(details, dealIds),
    companyIds: ids('companies').slice(0, CONFIG.MAX_ASSOCIATIONS),
  };
}

const inputs = $input.all();
const results = [];
for (let i = 0; i < inputs.length; i++) {
  const ev = inputs[i].json;
  const emit = (action, extra = {}) => results.push({ json: { ...ev, action, ...extra }, pairedItem: { item: i } });
  let match = null; let matchType = null;
  try {
    if (SANDBOX_MODE) {
      const s = SANDBOX_DIRECTORY[ev.caller.e164];
      if (s) { match = { contactId: s.contactId, contactName: s.contactName, contactOwnerId: s.contactOwnerId, dealIds: pickDeals(s.deals, s.deals.map((d) => d.id)), companyIds: s.companies }; matchType = 'sandbox_directory'; }
    } else {
      const found = await findContacts(ev.caller);
      if (found.length > 1 && CONFIG.MULTIPLE_MATCH_POLICY === 'skip') { emit('skip_ambiguous_caller', { reason: `${found.length}_contacts_share_this_number` }); continue; }
      if (found.length) { match = await loadContact(found[0].id); matchType = found.length > 1 ? 'most_recent_of_multiple' : 'phone_match'; }
    }
    if (!match && CONFIG.UNKNOWN_CALLER_POLICY === 'fallback_contact' && CONFIG.FALLBACK_CONTACT_ID) {
      match = SANDBOX_MODE ? { contactId: CONFIG.FALLBACK_CONTACT_ID, contactName: 'Unknown callers', contactOwnerId: null, dealIds: [], companyIds: [] } : await loadContact(CONFIG.FALLBACK_CONTACT_ID);
      matchType = 'fallback_contact';
    }
