  const base = { idempotencyKey: prep.idempotencyKey, provider: prep.provider, callId: prep.callId, contactId: prep.contactId, mode: prep.mode, correlationId: prep.correlationId };
  const emit = (action, extra = {}) => results.push({ json: { ...base, action, ...extra }, pairedItem: { item: i } });

  if (summary && summary.intent === 'spam_or_robocall' && CONFIG.SKIP_SPAM_NOTES) { emit('skip_spam', { reason: 'summary_classified_as_spam_or_robocall' }); continue; }

  const callerLabel = CONFIG.SHOW_CALLER_NUMBER === 'none' ? null : CONFIG.SHOW_CALLER_NUMBER === 'full' ? prep.caller.e164 : prep.caller.masked;
  const providerLabel = prep.provider === 'aircall' ? 'Aircall' : 'Twilio';
  const kindLabel = prep.kind === 'call_recording' ? 'Call recording' : 'Voicemail';
  const duration = prep.audioDurationSec ? mmss(prep.audioDurationSec) : null;

  let audioLink = null; let audioLabel = null;
  if (CONFIG.AUDIO_LINK_MODE === 'secure_provider_link' && prep.secureLink) { audioLink = safeHttpsLink(prep.secureLink); audioLabel = `Play recording in ${providerLabel} (login required)`; }
  else if (CONFIG.AUDIO_LINK_MODE === 'twilio_api_url' && prep.provider === 'twilio') { audioLink = safeHttpsLink(prep.audioUrl); audioLabel = 'Recording on Twilio (account credentials required)'; }

  const meta = [
    callerLabel ? `From: ${esc(callerLabel)}${prep.contactName ? ` (${esc(prep.contactName)})` : ''}` : (prep.contactName ? `From: ${esc(prep.contactName)}` : null),
    prep.lineName ? `Line: ${esc(prep.lineName)}` : null,
    prep.agentName ? `Agent: ${esc(prep.agentName)}` : null,
    duration ? `Duration: ${duration}` : null,
    `Source: ${providerLabel}`,
  ].filter(Boolean).join(' · ');

  const parts = [`<p><strong>${CONFIG.NOTE_TITLE_PREFIX ? `${esc(CONFIG.NOTE_TITLE_PREFIX)} ` : ''}${esc(kindLabel)} · ${esc(when(prep.startedAt))}</strong></p>`, `<p>${meta}</p>`];

  if (summary) {
    parts.push(`<p><strong>Summary:</strong> ${esc(summary.summary)}</p>`);
    parts.push(`<p>Intent: ${esc(INTENT_LABEL[summary.intent])} · Urgency: ${esc(summary.urgency)} · Callback requested: ${summary.callbackRequested ? `yes${summary.callbackBy ? ` (by ${esc(summary.callbackBy)})` : ''}` : 'no'} · Sentiment: ${esc(summary.sentiment)}</p>`);
    if (summary.actionItems.length) parts.push(`<p><strong>Action items</strong></p><ul>${summary.actionItems.map((a) => `<li>${esc(a)}</li>`).join('')}</ul>`);
    if (summary.keyDetails.length) parts.push(`<p><strong>Key details</strong></p><ul>${summary.keyDetails.map((a) => `<li>${esc(a)}</li>`).join('')}</ul>`);
  } else if (parsed.source === 'openai_error' || parsed.source === 'openai_unparseable') {
    parts.push('<p><em>AI summary unavailable for this voicemail. The transcript below is complete.</em></p>');
  }

  const header = `<p><strong>Transcript</strong> (auto-generated · ${esc(prep.transcriptionModel)}${prep.transcriptionLanguage ? ` · ${esc(prep.transcriptionLanguage)}` : ''}${prep.transcriptTruncated ? ' · truncated' : ''})</p>`;
  let transcriptHtml;
  if (prep.segments && prep.segments.length) transcriptHtml = `<p>${prep.segments.map((s) => `<strong>[${mmss(s.start)}]</strong> ${esc(s.text)}`).join('<br>')}</p>`;
  else if (prep.transcriptText) transcriptHtml = `<p>${esc(prep.transcriptText)}</p>`;
  else transcriptHtml = '<p><em>No speech detected in the recording.</em></p>';
  parts.push(header, transcriptHtml);

  if (audioLink) parts.push(`<p>🎧 <a href="${esc(audioLink)}">${esc(audioLabel)}</a></p>`);
  parts.push('<p><em>Transcribed automatically by the n8n voicemail transcriber (dhRobin Systems). Speech-to-text can mishear names, numbers and dates, so check the recording before acting on it.</em></p>');
  parts.push(`<p>Ref: ${esc(prep.idempotencyKey)}</p>`);

  let body = parts.join('');
  if (body.length > 60000) body = `${body.slice(0, 59900)}…</p>`;

  const associations = [];
  const add = (type, ids) => { for (const id of ids || []) if (ID.test(String(id))) associations.push({ to: { id: String(id) }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: NOTE_ASSOC[type] }] }); };
  add('contacts', [prep.contactId]);
  add('deals', prep.dealIds);
  add('companies', prep.companyIds);

  const properties = { hs_timestamp: new Date(prep.startedAt).toISOString(), hs_note_body: body };
  if (CONFIG.ASSIGN_NOTE_OWNER && prep.contactOwnerId) properties.hubspot_owner_id = String(prep.contactOwnerId);

  const dryRun = prep.mode ? prep.mode.dryRun !== false : true;
  emit(dryRun ? 'dry_run_would_create_note' : 'create_note', {
    reason: summary ? `summary_${parsed.source}` : `no_summary_${parsed.source}`,
    summaryError: parsed.error || null,
    intent: summary ? summary.intent : null,
    urgency: summary ? summary.urgency : null,
    callbackRequested: summary ? summary.callbackRequested : null,
    noteChars: body.length,
    linkedDealIds: prep.dealIds || [],
    notePayload: { properties, associations },
  });
}
return results;

// Audit Log — records the created HubSpot note and marks the call as processed (idempotency).
// Mode: Run Once for Each Item
const note = $('Build HubSpot Note').item.json;
