};
const isOn  = (key) => env(key, 'true').toLowerCase() !== 'false';   // fail-safe: ON unless exactly "false"
const optIn = (key) => env(key, 'false').toLowerCase() === 'true';   // opt-in: OFF unless exactly "true"
